import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Content Search","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/content-search.md","filePath":"user-guide/content-search.md","lastUpdated":1788190459000}'),s={name:"user-guide/content-search.md"};function o(r,e,d,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="content-search" tabindex="-1">Content Search <a class="header-anchor" href="#content-search" aria-label="Permalink to &quot;Content Search&quot;">​</a></h1><p>The Content Search plugin searches the text inside your local documents. It runs in the background and works alongside Lertaro&#39;s regular filename search.</p><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><p>Open <strong>Settings → Plugins → Content Search → Configure</strong>, set at least one monitored folder, then save. The default trigger keyword is <code>cs</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cs project plan</span></span></code></pre></div><p>The keyword must be followed by a space. Replace <code>cs</code> with another keyword in the plugin settings if it conflicts with your workflow.</p><h2 id="what-gets-indexed" tabindex="-1">What gets indexed <a class="header-anchor" href="#what-gets-indexed" aria-label="Permalink to &quot;What gets indexed&quot;">​</a></h2><ul><li><strong>Monitored folders</strong>: The plugin scans the configured local folders recursively. Environment variables such as <code>%USERPROFILE%</code> are supported.</li><li><strong>File extensions</strong>: The default list includes <code>txt</code>, <code>md</code>, <code>pdf</code>, <code>docx</code>, <code>docm</code>, <code>pptx</code>, <code>pptm</code>, <code>xlsx</code>, <code>xlsm</code>, and <code>csv</code>. You can change the comma-separated list to suit your files.</li><li><strong>PDF files</strong>: Searchable page text and saved values from fillable PDF form fields are included.</li><li><strong>File size</strong>: Files larger than the configured per-file limit are skipped. The content index also has a separate size cap; set it to <code>0</code> for unlimited size.</li><li><strong>Excluded paths</strong>: Add semicolon-separated regular expressions to exclude matching full paths. A match on a folder also excludes its contents.</li></ul><p>Files are only searched after their text has been extracted successfully. Binary files without a suitable document extractor are skipped instead of being indexed as unreadable text.</p><h2 id="searching" tabindex="-1">Searching <a class="header-anchor" href="#searching" aria-label="Permalink to &quot;Searching&quot;">​</a></h2><p>Type <code>cs</code> followed by a space and your keywords in the Quick Search Window. Matching files are shown with a text snippet and their containing folder; press <code>Enter</code> to open the selected file. When the query has results, the same file results are also available in the full search window when no type filter is active.</p><p>While the index is being built, the <code>cs</code> placeholder shows the number of indexed files and any remaining work. New and changed files are processed in the background, so regular filename search remains available during indexing.</p><h2 id="clearing-and-rebuilding" tabindex="-1">Clearing and rebuilding <a class="header-anchor" href="#clearing-and-rebuilding" aria-label="Permalink to &quot;Clearing and rebuilding&quot;">​</a></h2><p>The Content Search settings provide two separate actions:</p><ul><li><strong>Clear Index</strong> removes the content index without scanning the monitored files again.</li><li><strong>Rebuild Index</strong> removes the content index and scans all monitored files again.</li></ul><p>These actions affect only the Content Search index; Lertaro&#39;s normal filename index is not removed.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>If a file does not appear, check its folder, extension, exclusion patterns, and size limit in the plugin settings.</li><li>If you change the monitored folders or indexing rules, save the settings and allow the background scan to complete.</li><li>Use <strong>Rebuild Index</strong> after changing rules when you want existing files to be extracted again.</li></ul>',18)])])}const p=t(s,[["render",o]]);export{g as __pageData,p as default};
